Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
  ImageInfo *clone_info = CloneImageInfo(image_info);
  char filename[MaxTextLength];
  FILE *file;
  Image *new_image = (Image *) NULL;

  GetPathComponent(image->filename, NativePath, filename, MaxTextLength);
  (void) ConcatenatePath(filename, "ps_temp");
  (void) CopyMagickString(clone_info->filename, filename, MaxTextLength);

  file = fopen(clone_info->filename, "wb");
  if (file != (FILE *) NULL) {
    (void) fwrite(image->blob + PS_Offset, 1, (size_t) PS_Size, file);
    (void) fclose(file);

    clone_info = CloneImageInfo(clone_info);
    clone_info->size = "x";

    new_image = ReadImage(clone_info, exception);
    if (new_image != (Image *) NULL) {
      (void) CloneImageAttributes(image, new_image);
      DestroyImageList(image);
      image = new_image;
    }
  }

  if (new_image == (Image *) NULL)
    return (image);

  return (image);
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                                MagickOffsetType PS_Offset, ssize_t PS_Size,
                                ExceptionInfo *exception) {
  ImageInfo *clone_info;
  Image *new_image;
  StringInfo *blob;
  size_t blob_size;
  unsigned char *blob_data;
  char filename[MagickPathExtent];
  FILE *file;
  MagickBooleanType status;

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL) {
    ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
    return (Image *) image;
  }

  GetPathComponent(image->filename,TempName,filename);
  file = AllocateFileHandle();
  if (file == (FILE *) NULL) {
    DestroyImageInfo(clone_info);
    ThrowImageException(ResourceLimitError,"UnableToCreateTemporaryFile");
    return (Image *) image;
  }

  blob = GetImageBlob(image);
  if (blob == (StringInfo *) NULL) {
    CloseFile(file);
    DestroyImageInfo(clone_info);
    ThrowImageException(ResourceLimitError,"MemoryAllocationFailed");
    return (Image *) image;
  }

  blob_data = (unsigned char *) GetStringInfoDatum(blob);
  blob_size = (size_t) MagickMin(PS_Size, (ssize_t) GetStringInfoLength(blob));
  if (PS_Offset >= (MagickOffsetType) GetStringInfoLength(blob) ||
      PS_Offset + blob_size > (MagickOffsetType) GetStringInfoLength(blob)) {
    CloseFile(file);
    DestroyImageInfo(clone_info);
    ThrowImageException(CorruptImageError,"InvalidPostscriptOffsetOrSize");
    return (Image *) image;
  }

  if (fwrite(blob_data + (size_t) PS_Offset, sizeof(*blob_data), blob_size,
             file) != blob_size) {
    CloseFile(file);
    DestroyImageInfo(clone_info);
    ThrowImageException(ResourceLimitError,"UnableToWritePostscriptData");
    return (Image *) image;
  }

  CloseFile(file);

  clone_info->filename = (char *) filename;
  clone_info->size = MagickMin(clone_info->size,
                                 (size_t) MagickMin(clone_info->width,
                                                    blob_size));
  new_image = ReadImage(clone_info,exception);
  if (new_image == (Image *) NULL) {
    (void) remove(filename);
    DestroyImageInfo(clone_info);
    return (Image *) image;
  }

  status = SetImageProfile(image,"postscript",blob,exception);
  if (status == MagickFalse) {
    (void) remove(filename);
    DestroyImageInfo(clone_info);
    return (Image *) image;
  }

  (void) CloneImageAttributes(image,new_image,exception);
  (void) DestroyImage(new_image);
  (void) remove(filename);
  DestroyImageInfo(clone_info);
  return image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                              MagickOffsetType PS_Offset, ssize_t PS_Size,
                              ExceptionInfo *exception)
{
  Image
    *new_image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  char
    filename[MaxTextLength];

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    return image;

  GetPathComponent(image->filename, HeadPath, filename, MaxTextLength);
  (void) FormatLocaleString(&filename[strlen(filename)], MaxTextLength - strlen(filename),
                           "ps%05"PRIxPTR".ps", GetNextImageID());

  status = WriteImage(clone_info, image, filename);
  if (status == MagickFalse)
    return image;

  new_image = ReadImage(clone_info, exception);
  if (new_image == (Image *) NULL)
    return image;

  (void) CloneImageAttributes(image, new_image);
  DestroyImageList(image);
  image = new_image;

  RelinquishMemory(clone_info);
  (void) remove(filename);

  return image;
}
